<script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{adminLogin}from'../api/admin.js';import{User,Lock}from'@element-plus/icons-vue';const form=reactive({account:'admin',password:'123456',remember:true}),loading=ref(false),router=useRouter();async function submit(){loading.value=true;try{await adminLogin(form);ElMessage.success('登录成功');router.push('/requirements')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}</script>
<template><div class="login"><section class="visual"><div><h2>木序定制</h2><i></i><p>让设计、生产与交付有序协同</p></div></section><section class="login-form"><div class="box"><div class="login-brand"><strong>木序定制</strong><span>管理端</span></div><i></i><h1>登录管理平台</h1><el-form :model="form" label-position="top" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.account" :prefix-icon="User" placeholder="请输入账号"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" :prefix-icon="Lock" type="password" show-password placeholder="请输入密码"/></el-form-item><div class="options"><el-checkbox v-model="form.remember">记住登录状态</el-checkbox><a>忘记密码</a></div><el-button type="primary" native-type="submit" :loading="loading" style="width:100%;height:40px">登录</el-button></el-form><p class="safe">管理端为内部系统，请勿向他人泄露账号信息</p></div></section></div></template>
<style scoped>.login{min-height:100vh;display:grid;grid-template-columns:56% 44%;background:#fff}.visual{position:relative;background:center/cover url('../assets/admin-login-kitchen.png')}.visual:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(28,20,16,.65),transparent 50%)}.visual>div{position:absolute;z-index:1;left:10%;bottom:12%;color:#fff}.visual h2{font:500 36px var(--display);margin:0}.visual i,.box>i{display:block;width:34px;height:2px;background:var(--brass);margin:22px 0}.visual p{font:18px var(--display);letter-spacing:.06em}.login-form{display:grid;place-items:center;padding:40px}.box{width:min(430px,100%)}.login-brand{display:flex;align-items:center;gap:18px}.login-brand strong{font:500 34px var(--display)}.login-brand span{padding-left:18px;border-left:1px solid var(--border);color:var(--brass)}h1{font:500 30px var(--display);margin:0 0 30px}.options{display:flex;justify-content:space-between;margin:0 0 22px}.options a{color:var(--primary)}.safe{margin-top:60px;color:var(--muted);font-size:12px;text-align:center}@media(max-width:800px){.login{grid-template-columns:1fr}.visual{display:none}.login-form{padding:24px}}</style>
